// Health Career Display lessons 1–5: the event and choosing a health career, researching a career, job responsibilities
// and work settings, education and credentials, and salary, outlook, benefits and challenges.
const RULES=['HOSA Health Career Display 2026–27 guidelines and rating sheets','https://hosa.org/wp-content/uploads/2026/08/Health-Career-Display-26-27.pdf'];
const BLS_OOH=['U.S. Bureau of Labor Statistics: Occupational Outlook Handbook—healthcare occupations','https://www.bls.gov/ooh/healthcare/home.htm'];
const EHC=['Explore Health Careers','https://explorehealthcareers.org/'];
const NCHSE=['National Consortium for Health Science Education','https://www.healthscienceconsortium.org/'];
const ONET=['O*NET OnLine','https://www.onetonline.org/'];
const COS=['CareerOneStop','https://www.careeronestop.org/'];
const q=(p,a,b,c,d,e)=>[p,[a,b,c,d],e];
const match=(title,pairs)=>({t:'w',kind:'match',title,pairs});
const order=(title,steps)=>({t:'w',kind:'order',title,steps});
const sort=(title,buckets,items)=>({t:'w',kind:'sort',title,buckets,items});
const flip=(title,cards)=>({t:'w',kind:'flip',title,cards});
const kase=(title,nodes)=>({t:'w',kind:'case',title,start:'a',nodes});
const chk=(q,options,why)=>({t:'check',q,options,why});
const ex=(title,prompt,steps,answer)=>({t:'example',title,prompt,steps,answer});

export const HC1={title:'The event and choosing a health career',hook:'Health care includes more than 200 careers, from surgeons and nurses to sonographers, genetic counselors, health information technicians and biomedical engineers. Health Career Display asks two students to pick one of them, research it deeply and communicate it through a striking display board and a five-minute presentation. The career you choose shapes everything that follows.',objectives:['Describe the Health Career Display event, its rounds and scoring.','Explain what counts as a health career.','Use career clusters to explore options.','Choose a career your team can research and present well.'],sections:[
['The event at a glance',[
'Health Career Display is a **team event for two members**, open to middle school, secondary and postsecondary/collegiate divisions. The team chooses **one health career** and uses it for both rounds. **Round One** is a pre-judged **digital outline**—a slide-style plan of the display board, including **one photo of the completed board**—uploaded by one member as **one PDF** by **May 15**. It is worth **110 points**, and the outline may have **no more than 16 slides** plus reference slides.',
'At ILC, all teams must attend the **Required Project Display Time**, standing with their display and sharing career information; **missing it costs 15 points**. Top teams advance to **Round Two**, a **five-minute presentation** to judges using the display, worth **115 points**. Notecards are allowed (electronic notes are not shown), presenters may **pick up display items** and **both members** must take an active role.',
'The display is a **36″ × 48″ tri-fold board** with optional models and materials, all within **48″ wide × 24″ deep × 36″ high** on the table, with **no electricity or batteries**.',
{t:'table',caption:'Event structure',head:['Part','What you do','Points'],rows:[['Round One','Digital outline (≤16 slides + references) with board photo','110'],['Display Time','Stand with the display at ILC','−15 if missed'],['Round Two','5-minute presentation with the display','115'],['Final','Round One + Round Two','225']]}]],
['What counts as a health career',[
'The career must be a **health career**—one that directly provides, supports or advances health care, health information or health research. The guidelines note that careers such as **firefighter**, **flight attendant** and **special education teacher** are **not** classified as health careers, even though they may involve some health-related tasks.',
'Use the **National Consortium for Health Science Education (NCHSE)** and **Explore Health Careers** lists to confirm your choice. The outline’s first scored item checks that it reflects a health career or a cluster of related health careers; an ineligible career loses points immediately.',
'When in doubt, choose a career clearly listed in health career resources.',
sort('Health career?',['Health career','Not a health career'],[['Respiratory therapist',0],['Firefighter',1],['Diagnostic medical sonographer',0],['Flight attendant',1],['Health information technician',0],['Special education teacher',1]])]],
['Health science career clusters',[
'NCHSE groups health careers into **pathways**. **Therapeutic services** provide direct care (nurses, physicians, physical therapists, dental hygienists, pharmacists). **Diagnostic services** detect and diagnose disease (radiologic technologists, sonographers, medical laboratory scientists, phlebotomists). **Health informatics** manages health information (health information technicians, medical coders, health data analysts). **Support services** maintain a safe environment (biomedical equipment technicians, environmental services, central sterile processing). **Biotechnology research and development** advances science (biomedical engineers, research scientists, genetic counselors in some models).',
'Exploring each pathway helps you discover careers you might not have considered—and less familiar careers can make a display stand out.',
'Note that some careers fit more than one pathway.',
match('Career and pathway',[['Registered nurse','Therapeutic services'],['Sonographer','Diagnostic services'],['Medical coder','Health informatics'],['Biomedical equipment technician','Support services'],['Biomedical engineer','Biotechnology research and development'],['Medical laboratory scientist','Diagnostic services']])]],
['Choosing your career',[
'Choose a career that your team is **genuinely interested in**—judges score “why this career,” and real enthusiasm shows. Consider careers connected to your own goals, experiences (a family member’s care, a job shadow) or curiosity about a field.',
'Also consider **research availability**: Can you find reliable information on duties, education, salary and outlook? Could you interview or shadow a professional? Are there interesting objects or models you could display safely without electricity?',
'Avoid choosing solely because a career seems easy to present; depth of understanding earns more points.',
"It helps to write a short list of two or three finalists and spend a week reading about each. Notice which career keeps both members asking new questions; that curiosity usually becomes the energy judges see in Round Two.",
order('Choosing a career',['List careers that interest both members','Check each is a health career','Check that reliable information exists','Consider display and interview possibilities','Choose the career you are most excited to explain'])]],
['How judges score',[
'Round One judges score: **health-related career** and **title slide** (5 each); **career overview**, **job responsibilities** (five or more specific tasks for full points), **education requirements**, **entry-level salary at local/national/global levels**, **benefits and challenges**, **additional career information**, **creative and artistic impact** and the **photo of the display** (10 each, with some items scaled); plus **organization**, **references**, **originality** and **total slides** (no more than 16).',
'Round Two judges score the **display overview** (no power, safety, size), **display visuals** (artistic design, creativity, organization), **presentation content** (understanding of the career, why this career, presentation of career information, display incorporated) and **delivery** (voice, stage presence, diction, team participation).',
'Plan from the start to meet every item; several are easy points lost through carelessness, such as slide count or power use.',
flip('Easy points to protect',[['Health career','Choose a clearly listed health career'],['Title slide','Every required item on one slide'],['Total slides','No more than 16 plus references'],['Photo','Clear picture of the whole board'],['No power','No electricity, batteries or electronics'],['Display size','Within 48″ × 24″ × 36″']])]],
['A year-long plan',[
'**Fall:** choose the career, research it thoroughly and, if possible, interview or shadow a professional. **Winter:** design and build the display board and collect safe three-dimensional items. **Early spring:** photograph the finished board and build the digital outline, then proofread and upload well before **May 15**. **Late spring:** rehearse the five-minute presentation and the display-time conversation.',
'Keep a shared folder with research notes, sources (for APA references), interview notes, design sketches and photos. Divide tasks but make sure both members understand all of the content, since both must present.',
'Check your state conference’s process; if your state uses the HOSA upload system, upload again for ILC.',
order('Health Career Display timeline',['Choose and confirm a health career','Research and interview a professional','Design and build the board','Photograph the board','Build and upload the outline by May 15','Rehearse the presentation and display talk'])]],
['Practice scenario',[
kase('Picking a career',{a:{text:'Your team is deciding between “firefighter” and “emergency medical technician.” (Scenario invented for practice.) Which fits the event?',choices:[['Emergency medical technician—a recognized health career','b','Correct.',true],['Firefighter—it involves emergencies','b','The guidelines list firefighter as not a health career.',false]]},b:{text:'You want to show a working heart-monitor screen on your board. Is that allowed?',choices:[['No—electronics and batteries are not allowed; use a printed or modeled version','c','Correct.',true],['Yes, if it is small','c','No power of any kind is allowed.',false]]},c:{text:'You plan a printed ECG strip and a model stethoscope instead.',end:true}})]]
],takeaways:['Two-member team; one health career for both rounds; Round One is a pre-judged digital outline (≤16 slides plus references) with a photo of the finished board (110 points, one PDF by May 15); required ILC display time (−15 if missed); Round Two is a 5-minute presentation (115 points).','The career must be a health career (not firefighter, flight attendant or special education teacher); use NCHSE pathways—therapeutic, diagnostic, health informatics, support services, biotechnology research and development—and Explore Health Careers.','Choose a career you care about and can research deeply; plan for every rubric item; the board is a 36″ × 48″ tri-fold within 48″ × 24″ × 36″ with no electricity.'],terms:[['Health career','An occupation that provides, supports or advances health care, information or research.'],['Career pathway','A group of related careers, such as diagnostic services.'],['Display time','A required ILC session where teams share their display.']],mcqs:[q('How many members are on a Health Career Display team?','2','3','4','6','Pairs.'),q('Which is NOT classified as a health career by the guidelines?','Firefighter','Respiratory therapist','Sonographer','Pharmacist','Listed example.'),q('What is the maximum number of outline slides, not counting references?','16','10','25','30','Slide limit.'),q('What is the board size?','36″ × 48″ tri-fold','24″ × 24″ poster','48″ × 72″ banner','Any size','Single wall tri-fold.'),q('What happens if a team misses the Required Display Time?','A 15-point deduction','Disqualification','Nothing','Bonus points','From Round Two.'),q('How long is the Round Two presentation?','5 minutes','10 minutes','2 minutes','15 minutes','Time cards at one minute.'),q('Which pathway includes medical coders?','Health informatics','Therapeutic services','Support services','Diagnostic services','Information.'),q('Is electricity allowed on the display?','No','Yes','Only batteries','Only solar','No power of any kind.')],frq:{prompt:'Explain the Health Career Display event and how your team would choose a health career that will score well.',rubric:[['Event',['two','one career','outline','16 slides','photo','pdf','may 15','display time','5 minutes']],['Health career',['health career','firefighter','not','nchse','explore health careers','pathway']],['Choosing',['interest','research','reliable','interview','shadow','why']],['Scoring and planning',['rubric','no power','size','timeline','both members']]],model:'Health Career Display is a two-member team event in which we choose one health career and use it for both rounds. In Round One, we create a slide-style digital outline of no more than 16 slides plus references, describing the career overview, job responsibilities, education, entry-level salary, benefits and challenges, additional information and the creative design of our board, and including one clear photo of the finished display; one member uploads it as a single PDF by May 15, and it is worth 110 points. At ILC we must attend the required display time or lose 15 points, and the top teams give a five-minute presentation worth 115 points using our 36-by-48-inch tri-fold board, which must fit within 48 inches wide, 24 deep and 36 high, with no electricity or batteries. To choose a career, we would first list careers that interest both of us and confirm each is a true health career using the NCHSE pathways and Explore Health Careers, avoiding examples the guidelines exclude, such as firefighter. We would explore all five pathways—therapeutic, diagnostic, health informatics, support services and biotechnology research and development—to find a career that is meaningful to us, perhaps connected to a family experience or a job shadow, because judges score why we chose it. Finally, we would make sure reliable information exists on duties, education, salary and outlook, that we can interview a professional and that we can display safe, interesting objects, then choose the career we are most excited to explain.'},sources:[RULES,NCHSE,EHC]};

export const HC2={title:'Researching your health career',hook:'Judges reward information that is “accurate, current and presented in a logical manner.” That starts with research from reliable sources—and goes beyond websites to talking with people who do the job every day. Strong research gives your display substance and your presentation confidence.',objectives:['Use reliable career information sources such as the BLS Occupational Outlook Handbook and O*NET.','Evaluate career information for accuracy and currency.','Conduct an informational interview or job shadow professionally.','Organize research for the outline and display.'],sections:[
['Key career information sources',[
'The **Occupational Outlook Handbook (OOH)** from the **U.S. Bureau of Labor Statistics** describes hundreds of careers: what they do, work environment, how to become one, pay (median wages), job outlook, similar occupations and state and area data. **O*NET OnLine** lists detailed tasks, skills, knowledge, abilities, work activities and technology used in each occupation.',
'**Explore Health Careers** profiles many health careers with education paths and links to professional associations. **CareerOneStop** provides local wage data and training programs. **Professional associations** (for example, the American Society of Radiologic Technologists or the American Association for Respiratory Care) describe the profession, credentials and current issues.',
'Use several sources and compare them, noting dates.',
"Read each profile closely rather than skimming. The OOH “How to Become One” tab, for example, often lists important qualities and licensing details, while O*NET’s “Tasks” and “Technology Skills” sections supply the specific language that makes responsibilities slides strong.",
match('Source and best use',[['BLS Occupational Outlook Handbook','Duties, pay, outlook and how to enter'],['O*NET OnLine','Detailed tasks, skills and work activities'],['Explore Health Careers','Health career profiles and pathways'],['CareerOneStop','Local wages and training programs'],['Professional association','Credentials and current issues'],['Informational interview','Real-world perspective from a professional']])]],
['Evaluating information',[
'Check that information is **accurate** (from credible sources), **current** (recent data; wages and outlook change), **relevant** (about your exact career, not a similar one) and **specific** (concrete tasks and numbers rather than vague statements). Government (.gov) and professional association sources are generally reliable; school marketing pages and job ads may be biased.',
'Note **dates** on wage and outlook data and cite them. When sources disagree, explain the difference (for example, national median wage versus entry-level wage in your state).',
'Accurate, current information earns top scores for the career overview and other sections.',
sort('Reliable source for career data?',['Reliable','Use with caution'],[['BLS Occupational Outlook Handbook',0],['A for-profit school’s advertising page',1],['O*NET OnLine',0],['An anonymous forum post',1],['A professional association website',0],['An old article from many years ago',1]])]],
['Informational interviews',[
'An **informational interview** is a conversation with a professional to learn about their career—not to ask for a job. Contact professionals through your advisor, family, local hospitals or professional associations. Prepare questions in advance: What does a typical day look like? What education did you need? What do you enjoy most and find most challenging? What advice would you give students? How is technology changing the field?',
'Be professional: request a short meeting, arrive on time (in person or online), take notes, ask permission before quoting or photographing and send a thank-you note. Interview insights add authentic details and quotes to your display and presentation.',
'Job shadowing, where allowed, provides even richer understanding.',
"If an in-person visit is not possible, a video call or emailed questions can still work. Keep the request short, explain that the interview is for a HOSA competition and offer a few times that fit the professional’s schedule.",
order('Informational interview steps',['Identify a professional','Request a short meeting politely','Prepare focused questions','Conduct the interview and take notes','Ask permission to quote','Send a thank-you note'])]],
['Questions to answer',[
'Organize research around the outline sections: **career overview** (what the career is and why it matters), **job responsibilities** (five or more specific tasks), **education requirements** (degrees, courses, certificates, licenses, time to complete), **entry-level salary** at **local, national and global** levels, **benefits and challenges**, and **additional information** (outlook, specialties, advancement, professional organizations, technology, work settings).',
'Create a research table with one row per section and columns for facts, sources and dates. This makes building the outline and display much easier.',
'Look for **surprising facts**—they make displays memorable.',
"Divide research between both members, but meet regularly to share findings so each person understands every section. Judges may ask either member about any part of the career, and gaps in one person’s knowledge are easy to notice.",
flip('Outline sections to research',[['Career overview','What it is and why it matters'],['Job responsibilities','Five or more specific tasks'],['Education','Degrees, credentials and time required'],['Salary','Entry-level local, national and global'],['Benefits and challenges','Rewards and difficulties'],['Additional information','Outlook, specialties, advancement']])]],
['Citing your sources',[
'Every fact should be traceable to a source listed on your **reference slides**. **APA** style is preferred in health science; reference formatting is not judged, but a clean, legible reference page earns points. Basic APA web reference: Author or organization. (Year, Month Day). *Title of page*. Site Name. URL.',
'Keep a running list as you research so you do not lose sources. Cite interviews as personal communications in text if your teacher requires.',
'Accurate citation also shows judges the depth of your research.',
ex('APA reference for a web page','Write an APA reference for a BLS career page (date invented for practice).',['Author: U.S. Bureau of Labor Statistics','Date: (2026, September 1) or the page’s update date','Title in italics: Respiratory therapists','Source: Occupational Outlook Handbook','URL: the page address'],'U.S. Bureau of Labor Statistics. (2026, September 1). *Respiratory therapists*. Occupational Outlook Handbook. https://www.bls.gov/… (date invented for practice).')]],
['Turning research into a story',[
'Facts alone do not make a strong display. Organize research into a **story**: Who are these professionals? What do they do for patients? How do you become one? What is the work really like? Where is the career headed? Connect facts to people—a patient helped, a problem solved.',
'Choose a **theme** or tagline that captures the career (“Every breath matters” for respiratory therapy; “Seeing the unseen” for sonography). A theme guides both the board design and the presentation.',
'Your story should also explain **why your team chose** the career and **what you learned**, which judges score in Round Two.',
chk('Which tagline best supports a respiratory therapy display?',['“Every breath matters”','“Careers are fun”','“Health is good”','“Read our board”'],'A specific theme ties the display together.')]],
['Practice scenario',[
kase('Research gaps',{a:{text:'Your team found national wage data but nothing local. (Scenario invented for practice.) What do you do?',choices:[['Use CareerOneStop or state labor data for local wages and cite them','b','Correct.',true],['Guess a local number','b','Never invent data.',false]]},b:{text:'A professional you interviewed shares a memorable patient story. How do you use it?',choices:[['Ask permission, remove identifying details and paraphrase it in the presentation','c','Correct.',true],['Post the patient’s name on the board','c','Protect privacy.',false]]},c:{text:'Your research table now covers every outline section with dated sources.',end:true}})]]
],takeaways:['Use the BLS Occupational Outlook Handbook (duties, pay, outlook, entry), O*NET (tasks, skills), Explore Health Careers, CareerOneStop (local wages) and professional associations; compare several sources.','Evaluate information for accuracy, currency, relevance and specificity; note dates; conduct professional informational interviews or job shadows and send thanks.','Organize research by outline section in a table, cite every fact in APA style and turn facts into a story with a theme, including why you chose the career and what you learned.'],terms:[['Occupational Outlook Handbook','A BLS guide to careers, pay and outlook.'],['Informational interview','A conversation with a professional to learn about a career.'],['O*NET','A database of occupational tasks, skills and work activities.']],mcqs:[q('Which source provides detailed tasks and skills for occupations?','O*NET OnLine','A job ad','A social media post','A brochure from a for-profit school','Occupational database.'),q('Which BLS publication describes pay and job outlook?','Occupational Outlook Handbook','MMWR','Federal Register','Healthy People 2030','BLS.'),q('Which source helps find local wage data?','CareerOneStop','A celebrity blog','An old textbook','A random forum','Local data.'),q('An informational interview is meant to:','Learn about a career','Ask for a job','Sell a product','Test the professional','Learning.'),q('Which reference style is preferred?','APA','MLA only','None','Chicago only','Health science.'),q('Which information quality matters most for wage data?','Currency (recent dates)','Font size','Number of pictures','Length','Wages change.'),q('What should you do after an informational interview?','Send a thank-you note','Post their phone number','Ignore them','Ask for money','Professional courtesy.'),q('Why choose a theme or tagline?','It ties the display and presentation together','It replaces research','It adds slides','It is required by law','Story.')],frq:{prompt:'Describe how your team would research a health career for Health Career Display, including sources, evaluation, an informational interview and organization.',rubric:[['Sources',['occupational outlook handbook','bls','o*net','explore health careers','careeronestop','association']],['Evaluation',['accurate','current','dates','relevant','specific','compare']],['Interview',['informational interview','questions','professional','permission','thank-you','shadow']],['Organization',['research table','sections','apa','references','story','theme']]],model:'Our team chose to research sonography. We would begin with the BLS Occupational Outlook Handbook for an overview of what diagnostic medical sonographers do, their work environment, how to enter the field, median pay and job outlook, then use O*NET to list detailed tasks, skills and technology, Explore Health Careers for the education pathway and professional organizations such as the Society of Diagnostic Medical Sonography for credentials and current issues. CareerOneStop and our state’s labor data would provide local entry-level wages, and we would look for international comparisons for the global salary requirement. We would evaluate each source for accuracy, currency and relevance, noting the date of every wage or outlook figure and explaining differences between national medians and local entry-level pay. To add real-world depth, we would ask our advisor to connect us with a sonographer at a local hospital for a short informational interview, preparing questions about a typical day, education, rewards, challenges and changes in technology, taking notes, asking permission before quoting them and sending a thank-you note. We would organize everything in a research table with rows for each outline section—overview, at least five job responsibilities, education, salary, benefits and challenges and additional information—listing facts, sources and dates, and keep APA references as we go. Finally, we would shape the research into a story around a theme such as “Seeing the unseen,” including why we chose sonography and what surprised us.'},sources:[RULES,BLS_OOH,ONET,COS]};

export const HC3={title:'Job responsibilities and work settings',hook:'“Takes care of patients” describes almost every health career—and earns almost no points. Judges award full credit for job responsibilities only when the outline gives detailed information and describes five or more tasks specific to the career. This lesson shows how to describe what professionals actually do, where they work and what skills they need.',objectives:['Describe at least five specific tasks for a health career.','Describe work settings, schedules and teams.','Identify technical and interpersonal skills needed.','Present responsibilities clearly on slides and the board.'],sections:[
['From general to specific tasks',[
'Specific tasks show real understanding. Compare a vague description—“A respiratory therapist helps patients breathe”—with specific tasks: **evaluates patients’ breathing** with tests such as pulse oximetry and arterial blood gases; **administers aerosol medications** with nebulizers and inhalers; **manages mechanical ventilators** for critically ill patients; **performs airway clearance** techniques; **responds to emergencies** such as cardiac arrest; and **educates patients** with asthma or COPD on inhaler use.',
'Use **action verbs** (assesses, administers, operates, documents, educates, collaborates) and include **equipment**, **procedures** and **patient populations**. O*NET task lists and interviews with professionals are excellent sources.',
'Aim for **five or more** clear, career-specific tasks to earn full points.',
"Patient populations matter too. A pediatric respiratory therapist, a neonatal therapist and a therapist in a sleep laboratory perform different daily tasks, so state which population your examples describe and note how the work changes across them.",
sort('Specific or vague task?',['Specific','Vague'],[['Manages mechanical ventilators for ICU patients',0],['Helps people',1],['Performs ultrasound scans of the abdomen and heart',0],['Works in health care',1],['Codes diagnoses using ICD-10-CM',0],['Is very busy',1]])]],
['A day in the life',[
'Describing a **typical day** helps judges picture the career. A sonographer might review orders, prepare the room and equipment, explain the procedure, position the patient, capture and evaluate images, document findings for the physician and clean equipment between patients. A health information technician might review records for completeness, assign codes, check data accuracy and protect privacy.',
'Include how the work varies—emergencies, different patient ages, special procedures—and how professionals communicate with teams.',
'A short “day in the life” timeline makes an engaging board panel or slide.',
"Interviews are the best source for this panel. Ask the professional to walk you through yesterday’s shift hour by hour, including breaks, paperwork and surprises, and use those details to make your timeline realistic rather than idealized.",
order('Example sonographer workflow',['Review the physician’s order','Prepare the room and equipment','Explain the exam to the patient','Position the patient and capture images','Evaluate image quality and document findings','Clean equipment and prepare for the next patient'])]],
['Work settings and schedules',[
'Health professionals work in many **settings**: hospitals, outpatient clinics, physician offices, laboratories, long-term care facilities, home health, schools, public health agencies, research institutions, industry and telehealth. Some work behind the scenes; others have constant patient contact.',
'Describe **schedules** (day, night or rotating shifts; weekends and holidays in hospitals; regular hours in offices), **physical demands** (standing, lifting, repetitive motion) and **team relationships** (who they work with and report to).',
'Settings and schedules are part of the career overview and may count as additional relevant information.',
"Telehealth and remote work have changed several careers. Some coders, health information technicians and even therapists now work partly from home, which can be an interesting point for the additional information section.",
match('Career and common setting',[['Respiratory therapist','Hospital ICUs and emergency departments'],['Medical laboratory scientist','Hospital and reference laboratories'],['Physical therapist','Outpatient clinics and hospitals'],['Health information technician','Hospital records departments or remote work'],['Home health aide','Patients’ homes'],['Biomedical engineer','Medical device companies and research labs']])]],
['Skills and personal qualities',[
'Careers require **technical skills** (operating equipment, performing procedures, using electronic health records) and **interpersonal skills** (communication, empathy, teamwork). Important personal qualities often include **attention to detail**, **critical thinking**, **physical stamina**, **emotional resilience**, **cultural humility** and **integrity**.',
'O*NET lists skills and abilities for each occupation, and the OOH describes important qualities. Professionals in interviews can tell you which qualities matter most in practice.',
'Linking skills to your own strengths can strengthen your “why this career” explanation.',
"Be honest about the physical and emotional demands as well. A career that requires lifting patients or long periods of standing suits some people better than others, and judges appreciate a realistic picture rather than a recruitment advertisement.",
sort('Technical skill or personal quality?',['Technical skill','Personal quality'],[['Operating an ultrasound machine',0],['Empathy',1],['Drawing blood with proper technique',0],['Attention to detail',1],['Using ICD-10 coding software',0],['Emotional resilience',1]])]],
['The health care team',[
'No health professional works alone. Show how your career fits into the **health care team**: who orders their services, who they collaborate with and who relies on their work. For example, a sonographer works with radiologists and cardiologists who interpret images; a respiratory therapist collaborates with nurses and physicians in the ICU; a medical laboratory scientist provides results that physicians use to diagnose and treat.',
'Interprofessional collaboration improves patient safety and outcomes. A simple diagram on your board showing these relationships can be visually effective.',
'Understanding the team also shows judges a deep understanding of the career.',
"A simple team diagram can place your career in the center with arrows to the professionals who send work to it and the professionals who rely on its results. This shows judges you understand how the career supports patient care.",
match('Career and key collaborator',[['Sonographer','Radiologist or cardiologist'],['Respiratory therapist','ICU nurses and physicians'],['Pharmacy technician','Pharmacist'],['Medical coder','Physicians and billing staff'],['Physical therapist assistant','Physical therapist'],['Phlebotomist','Laboratory staff']])]],
['Presenting responsibilities visually',[
'On slides and the board, present responsibilities as a **numbered list**, **icons** with short labels or a **day-in-the-life timeline**. Keep text concise—five to eight words per task—with detail saved for the presentation. Photos (used legally) of equipment or settings help viewers understand unfamiliar tasks.',
'The outline allows **up to two slides** for job responsibilities, so prioritize the most important and interesting tasks.',
'Use consistent design with the rest of your display.',
"Before finalizing the slide, compare your task list with O*NET and your interview notes. If a professional says a task is rare in practice, move it lower on the list or leave it out in favor of the work they do every day.",
chk('How many specific tasks earn full points for job responsibilities?',['Five or more','One','Two','Three'],'Detailed information with 5+ specific tasks.')]],
['Practice scenario',[
kase('Strengthening responsibilities',{a:{text:'Your draft slide says, “Medical lab scientists test things.” (Scenario invented for practice.) What would improve it most?',choices:[['List five specific tasks, such as analyzing blood samples, performing cultures and verifying instrument quality control','b','Correct.',true],['Add a larger font','b','Content is the problem.',false]]},b:{text:'How can you present the tasks visually?',choices:[['Icons with short labels or a day-in-the-life timeline','c','Correct.',true],['A paragraph of small text','c','Keep it concise and visual.',false]]},c:{text:'Your revised slide earns full points for detail and clarity.',end:true}})]]
],takeaways:['Describe five or more specific, career-specific tasks using action verbs, equipment, procedures and patient populations—vague descriptions earn little.','Include a day in the life, work settings, schedules and physical demands, technical skills and personal qualities and how the career fits on the health care team.','Present responsibilities concisely with numbered lists, icons or timelines, within two slides, using O*NET and interviews as sources.'],terms:[['Job responsibility','A specific task performed in a career.'],['Work setting','The place where a professional works.'],['Interprofessional collaboration','Professionals from different fields working together.']],mcqs:[q('How many specific tasks earn full points?','Five or more','One','Two','Three','Rubric.'),q('Which is a specific task?','Manages mechanical ventilators for ICU patients','Helps people','Works hard','Likes medicine','Detail.'),q('Which source lists detailed tasks for occupations?','O*NET','A brochure','A movie','A slogan','Database.'),q('Which is a technical skill?','Operating an ultrasound machine','Empathy','Resilience','Integrity','Hands-on.'),q('Which is a personal quality?','Attention to detail','Coding software','Drawing blood','Running a ventilator','Character trait.'),q('How many slides are allowed for job responsibilities?','Up to two','Up to ten','One only','Unlimited','Section limit.'),q('A sonographer works closely with:','Radiologists or cardiologists','Firefighters','Pilots','Teachers only','Interpret images.'),q('Which best presents tasks visually?','Icons with short labels','A paragraph of small text','No visuals','Random photos','Concise.')],frq:{prompt:'Describe the job responsibilities, work settings and skills of a health career of your choice in a way that would earn full points.',rubric:[['Specific tasks',['five','tasks','assesses','administers','operates','documents','educates']],['Day and settings',['day','setting','hospital','clinic','schedule','shifts']],['Skills',['technical','interpersonal','communication','detail','empathy','resilience']],['Team and presentation',['team','collaborates','icons','timeline','concise','two slides']]],model:'For respiratory therapy, we would describe at least six specific responsibilities: evaluating patients’ breathing with pulse oximetry, spirometry and arterial blood gas results; administering aerosol medications through nebulizers and inhalers; setting up and managing mechanical ventilators for critically ill patients; performing airway clearance techniques such as chest physiotherapy; responding to emergencies, including cardiac arrest and newborn resuscitation; and educating patients with asthma or COPD on inhaler technique and home oxygen. A day in the life might include morning rounds in the ICU, ventilator checks, breathing treatments on medical floors, an emergency response and patient education before discharge, with documentation throughout. Respiratory therapists work mainly in hospitals—ICUs, emergency departments and neonatal units—but also in sleep labs, home care and rehabilitation, often on 12-hour day or night shifts that include weekends and holidays. They need technical skills such as operating ventilators and interpreting blood gas results, and personal qualities such as attention to detail, calm under pressure, compassion and clear communication, because they work closely with nurses, physicians and other therapists as part of the care team. On our slides and board, we would show the tasks as a numbered list with simple icons—a ventilator, a nebulizer, a lung—and a short day-in-the-life timeline, keeping each task to a few words and saving details for the presentation.'},sources:[RULES,ONET,BLS_OOH]};

export const HC4={title:'Education, licensure and certification',hook:'Becoming a health professional can take a few months or more than a decade. Judges award full points for a detailed, thorough description of educational requirements—degrees, courses, certificates, licenses, special requirements and the estimated time to complete them. A clear education pathway also helps classmates see how they could enter the career.',objectives:['Describe education levels for health careers, from certificates to doctoral degrees.','Distinguish licensure, certification and registration.','Explain accreditation and continuing education.','Present an education pathway with estimated time.'],sections:[
['Levels of education',[
'Health careers require different levels of education. **Postsecondary certificates or diplomas** (weeks to about a year) prepare nursing assistants, phlebotomists, pharmacy technicians and EMTs. **Associate degrees** (about two years) prepare many respiratory therapists, radiologic technologists, dental hygienists, sonographers and registered nurses. **Bachelor’s degrees** (about four years) prepare many registered nurses, medical laboratory scientists, dietitians and health administrators.',
'**Master’s degrees** prepare physician assistants, occupational therapists, speech-language pathologists, genetic counselors and nurse practitioners. **Doctoral or professional degrees** prepare physicians (medical school plus residency), pharmacists, physical therapists, dentists, optometrists and veterinarians.',
'Many careers allow more than one entry route; state the most common route and note alternatives.',
"Some careers are changing their entry requirements over time. For example, several professions have moved toward higher entry degrees, so check current sources and note any transition that affects students starting today.",
match('Career and common entry education',[['Phlebotomist','Postsecondary certificate'],['Dental hygienist','Associate degree'],['Medical laboratory scientist','Bachelor’s degree'],['Physician assistant','Master’s degree'],['Physical therapist','Doctor of Physical Therapy'],['Physician','Medical degree plus residency']])]],
['High school preparation and courses',[
'High school students can prepare by taking **biology**, **chemistry**, **anatomy and physiology**, **math** and **health science** courses, joining HOSA, earning certifications such as CPR, volunteering and job shadowing. Some schools offer dual-credit or career and technical education programs that lead to entry-level certifications.',
'College programs often require **prerequisite courses** such as anatomy and physiology, microbiology, chemistry, statistics and medical terminology. Programs may also require observation hours, entrance exams and interviews.',
'Including high school steps makes your education slide practical for classmates.',
order('Example pathway to respiratory therapy',['High school science and health courses','Prerequisites such as anatomy, chemistry and math','Accredited associate or bachelor’s RT program','Clinical rotations','National credentialing exam (RRT)','State license'])]],
['Licensure, certification and registration',[
'**Licensure** is granted by a **state** and is legally required to practice certain professions (for example, registered nurses, physicians, pharmacists, respiratory therapists in most states). **Certification** is usually granted by a **professional organization** after passing an exam and shows competence; it may be voluntary or required by employers. **Registration** is listing with a registry, sometimes after passing an exam (for example, Registered Respiratory Therapist, Registered Dietitian).',
'Name the specific credentials and exams for your career—such as the **NCLEX-RN** for registered nurses, the **ARRT** exam for radiologic technologists or the **PANCE** for physician assistants—and the organizations that grant them.',
'Distinguishing these terms shows judges deep understanding.',
"Requirements vary by state, so check the licensing board in your own state as well as national sources. Mention any extra requirements such as background checks, immunizations, drug screening or CPR certification that programs and employers commonly require.",
sort('Licensure or certification?',['Licensure (state)','Certification (professional organization)'],[['Legally required to practice as an RN',0],['Credential from a professional exam board',1],['Granted by a state board',0],['May be voluntary or required by employers',1],['State permission to practice medicine',0]])]],
['Accreditation and clinical training',[
'**Accredited programs** meet quality standards set by recognized accrediting organizations, and graduating from one is often required to sit for credentialing exams. Examples include CAAHEP for many allied health programs, CoARC for respiratory care, JRCERT for radiography and ACEN or CCNE for nursing.',
'Most health programs include **clinical rotations**—supervised hands-on training in real health care settings. Some careers require **residencies** or **fellowships** after graduation (for example, physicians and some pharmacists).',
'Advise viewers to choose accredited programs to keep career options open.',
"You can find accredited programs through the accrediting organizations’ own directories. Mentioning one or two programs near your school makes the education slide more practical for classmates considering the career.",
chk('Why choose an accredited program?',['Graduation is often required to take credentialing exams','It is always cheaper','It guarantees a job','It removes the need for clinical training'],'Accreditation affects eligibility.')]],
['Continuing education and advancement',[
'Most licensed and certified professionals must complete **continuing education (CE)** to renew credentials, keeping up with new technology and research. Advancement often comes through **specialty certifications** (for example, neonatal respiratory care or cardiac sonography), **advanced degrees** (an RN earning a master’s to become a nurse practitioner) or **leadership roles**.',
'Describing a **career ladder**—entry, specialization, advanced practice, leadership—shows how the career can grow over time.',
'This information can appear on the education or additional information slides.',
"Ask your interviewee how they advanced in their own career. Real examples, such as a technologist who earned a specialty credential and became a department lead, help viewers picture growth beyond the first job.",
order('Example career ladder in nursing',['Certified nursing assistant','Licensed practical nurse','Registered nurse','Specialty certification','Nurse practitioner or nurse leader'])]],
['Estimating time and presenting the pathway',[
'The rubric asks for the **estimated time** to complete requirements. Add up each stage: for example, “High school diploma, plus about two years for an associate degree in respiratory therapy, plus passing national exams—about two to three years after high school.” For physicians: four years of college, four years of medical school and three to seven years of residency.',
'Present the pathway visually as a **timeline**, **staircase** or **road map** on your board, with years labeled. Include costs or financial aid tips only if accurate and sourced.',
"Remember that time estimates are averages. Part-time study, prerequisite courses taken after high school or waiting lists for competitive programs can lengthen the path, so describe the typical route and note common variations.",
ex('Estimating time for a career','Estimate time after high school to become a physical therapist (typical U.S. route).',['Bachelor’s degree with prerequisites: about 4 years','Doctor of Physical Therapy program: about 3 years','Pass the national licensing exam and obtain a state license','Total: about 7 years after high school'],'About 7 years after high school, plus licensure (typical route; verify with current sources).')]],
['Practice scenario',[
kase('Education slide',{a:{text:'Your slide says, “You need college to be a sonographer.” (Scenario invented for practice.) What is missing?',choices:[['Degree type, program accreditation, credentialing exams and estimated time','b','Correct.',true],['Nothing','b','The rubric wants detail.',false]]},b:{text:'How do you present the pathway?',choices:[['A labeled timeline from high school courses to an accredited program, clinical training and the credentialing exam','c','Correct.',true],['A single sentence','c','A visual pathway is clearer.',false]]},c:{text:'Your revised slide earns full points for education requirements.',end:true}})]]
],takeaways:['Education ranges from certificates (phlebotomist, EMT) to associate (dental hygienist, many RTs), bachelor’s (MLS), master’s (PA, OT) and doctoral degrees (PT, PharmD, MD with residency); include high school preparation and prerequisites.','Licensure is state permission to practice; certification comes from professional organizations; registration lists credentialed professionals; name specific exams (NCLEX-RN, ARRT, PANCE) and accredited programs with clinical rotations.','Include continuing education, specialty certifications and a career ladder; estimate the total time to enter the career and present it as a timeline or road map.'],terms:[['Licensure','State permission required to practice a profession.'],['Certification','A credential from a professional organization showing competence.'],['Accreditation','Recognition that an educational program meets quality standards.']],mcqs:[q('Licensure is granted by:','A state','A professional organization only','A hospital','A school club','Legal requirement.'),q('Certification is usually granted by:','A professional organization','The federal government only','A patient','A hospital cafeteria','Exam-based.'),q('Which exam do registered nurses take?','NCLEX-RN','PANCE','ARRT','MCAT','Licensure exam.'),q('Physician assistants typically need a:','Master’s degree','Certificate only','High school diploma','Associate degree','Graduate level.'),q('Why choose an accredited program?','It is often required to take credentialing exams','It is always shorter','It guarantees wealth','It skips clinicals','Eligibility.'),q('Continuing education is needed to:','Renew credentials and stay current','Start high school','Avoid licensure','Replace degrees','Lifelong learning.'),q('About how long after high school is the typical route to physical therapist?','About 7 years','About 1 year','About 15 years','About 3 months','Bachelor’s plus DPT.'),q('Which is a high school preparation step?','Taking anatomy and physiology','Skipping science','Avoiding volunteering','Ignoring HOSA','Preparation.')],frq:{prompt:'Describe the complete education and credentialing pathway for a health career of your choice, including estimated time.',rubric:[['Education',['degree','certificate','associate','bachelor','master','doctoral','prerequisites','high school']],['Credentials',['licensure','state','certification','exam','registration','accredited']],['Training and growth',['clinical','rotations','residency','continuing education','specialty','ladder']],['Time and presentation',['years','estimated','total','timeline','road map']]],model:'To become a diagnostic medical sonographer, a student can prepare in high school with biology, anatomy and physiology, physics, math and health science courses, HOSA membership and job shadowing. After high school, the most common route is an associate degree in diagnostic medical sonography from a program accredited by CAAHEP, taking about two years, though bachelor’s programs and one-year certificate programs for people who already hold health degrees are also available. Programs require prerequisites such as anatomy and physiology, physics and medical terminology, and include extensive clinical rotations in hospitals and imaging centers. After graduation, sonographers usually earn certification by passing exams from a professional credentialing organization such as the American Registry for Diagnostic Medical Sonography, which most employers require; a few states also require a license. Certified sonographers complete continuing education to maintain their credentials and can add specialty certifications in areas such as cardiac, vascular or obstetric sonography, or advance into lead sonographer, education or management roles. In total, a typical student can enter the career about two to three years after high school. On our board, we would present this as a labeled road map from high school courses to an accredited program, clinical training, the certification exam, a first job and specialty growth, with the years marked at each step and every requirement cited from current sources.'},sources:[RULES,BLS_OOH,EHC]};

export const HC5={title:'Salary, outlook, benefits and challenges',hook:'“How much does it pay?” is one of the first questions classmates ask about a career. The outline requires entry-level salary at the local, national and global levels—not just a single number—and a balanced look at benefits and challenges. Accurate, well-explained data make your display trustworthy and useful.',objectives:['Find entry-level salary data at local, national and global levels.','Distinguish entry-level, median and experienced pay.','Describe job outlook and factors driving demand.','Present balanced benefits and challenges of a career.'],sections:[
['Understanding salary data',[
'Salary data come in different forms. The **median** wage is the middle value—half earn more, half less. **Entry-level** pay is usually near the **lower percentiles** (for example, the 10th or 25th percentile). Data may be **annual** salaries or **hourly** wages. Experienced professionals and specialists typically earn more.',
'The rubric specifically asks for **entry-level salary**, so do not present only the median. If a source gives percentiles, explain which value approximates entry level and cite the date.',
'Be careful to compare like with like: annual versus hourly, national versus local and the same year.',
flip('Salary terms',[['Median','Middle value; half earn more, half less'],['10th percentile','Often close to entry-level pay'],['Annual wage','Yearly pay'],['Hourly wage','Pay per hour'],['Entry level','Pay for new graduates'],['Experienced pay','Higher with years and specialization']])]],
['Local, national and global salary',[
'**National** data come from the BLS Occupational Outlook Handbook and Occupational Employment and Wage Statistics. **Local** data (your state or metropolitan area) come from BLS state and area data, **CareerOneStop** or your state labor department. **Global** data are harder to find; use reputable international sources, such as government labor statistics in other countries or international professional organizations, and note differences in currency, cost of living and how the profession is structured.',
'If reliable global data are limited, say so honestly and compare one or two countries with clear sources rather than inventing figures.',
'Cost of living matters: a higher salary in an expensive city may not mean more buying power.',
"When using BLS data, look for the occupation’s profile in the Occupational Employment and Wage Statistics tables, which list the 10th, 25th, median, 75th and 90th percentile wages. State and metropolitan tables use the same format, making local and national comparisons straightforward.",
match('Data need and source',[['National median wage','BLS Occupational Outlook Handbook'],['State or metro wages','BLS state and area data or CareerOneStop'],['Another country’s wages','That country’s government labor statistics'],['Entry-level estimate','Lower percentile values'],['Cost of living','Explains local differences'],['Currency conversion','Needed for global comparisons']])]],
['Job outlook',[
'**Job outlook** projects how employment will change over about ten years. The BLS reports projected growth rates and the number of openings expected each year. Many health careers are projected to grow because of an **aging population**, rising rates of **chronic disease**, **advances in technology** and expanding **outpatient and home care**.',
'Outlook varies by career and location—some fields face shortages in rural areas. Explain **why** demand is changing, not just the percentage.',
'Outlook can appear in the overview or additional information sections.',
"Outlook can differ sharply by region. A career with average national growth may have serious shortages in rural communities, which can be a meaningful point if your school is in a rural or underserved area.",
sort('Factor increasing demand?',['Increases demand','Not a typical driver'],[['Aging population',0],['More chronic disease',0],['New imaging technology',0],['Fewer people needing care',1],['Expansion of outpatient care',0]])]],
['Benefits of the career',[
'**Benefits** include both **job-related** advantages—salary, health insurance and retirement plans, job security, flexible or part-time options, opportunities to specialize and advance—and **personal rewards**, such as helping patients, intellectual challenge, teamwork and meaningful work.',
'Use specific examples: “Respiratory therapists help newborns breathe in neonatal ICUs,” or “Health information technicians may work remotely.” Interview quotes about what professionals love about their jobs add authenticity.',
'Benefits help explain why someone—and your team—would choose this career.',
"Benefits packages vary by employer, so describe common patterns rather than promising specific benefits. Phrases such as “many hospital employers offer” keep your statements accurate.",
chk('Which is a personal reward of a health career?',['Helping patients recover','A specific pay rate','Health insurance','A retirement plan'],'Personal rewards complement job benefits.')]],
['Challenges of the career',[
'Every career has **challenges**: **physical demands** (standing, lifting, repetitive motions), **emotional stress** (critical patients, grief), **schedules** (nights, weekends, holidays, on-call), **exposure risks** (infections, radiation, chemicals), **continuing education** requirements, **cost and length of education** and **burnout**.',
'Present challenges honestly but constructively, noting how professionals manage them—teamwork, protective equipment, self-care, scheduling choices. Balanced information builds trust with judges and viewers.',
'The outline allows up to two slides for benefits and challenges; a two-column comparison is effective.',
"Interview the professional about challenges as well as rewards. Asking “What is the hardest part of your job, and how do you handle it?” often produces the most memorable and honest material for the presentation.",
sort('Benefit or challenge?',['Benefit','Challenge'],[['Strong job outlook',0],['Night and weekend shifts',1],['Helping patients breathe easier',0],['Exposure to infectious diseases',1],['Opportunities to specialize',0],['Emotional stress with critical patients',1]])]],
['Presenting numbers clearly',[
'Show salary data in a simple **table** or **bar chart** labeled “Entry-level (local),” “Entry-level (national),” “International example,” with **source and year** beneath. Round numbers for readability and specify annual or hourly. Avoid cluttering the board with too many figures.',
'In the presentation, explain what the numbers mean: “New respiratory therapists in our state start at about [figure], somewhat below the national entry-level estimate, likely because of lower living costs.”',
"Be ready to explain every figure aloud. A judge may ask why the local number is lower than the national one, and a confident answer about cost of living or regional demand shows that you understand the data rather than just copying it.",
ex('Comparing salary data','Present entry-level salary for a career using invented figures.',['Local entry-level (state, 25th percentile): $52,000 per year','National entry-level (25th percentile): $58,000 per year','International example (another country, converted): about $45,000 per year','Note: different costs of living and data years','Cite each source with its date'],'A labeled comparison of local, national and global entry-level pay (figures invented for practice).')]],
['Practice scenario',[
kase('Salary slide',{a:{text:'Your draft salary slide shows only the national median. (Scenario invented for practice.) What is missing?',choices:[['Entry-level figures at local, national and global levels with sources and dates','b','Correct.',true],['Nothing','b','The rubric requires entry-level local, national and global data.',false]]},b:{text:'You cannot find reliable global data for your exact career. What do you do?',choices:[['Use a reputable source for one comparable country and explain limitations','c','Correct.',true],['Make up a global number','c','Never invent data.',false]]},c:{text:'Your revised slide is accurate, honest and easy to read.',end:true}})]]
],takeaways:['Present entry-level pay (often near lower percentiles), not just the median; specify annual or hourly, source and year; compare local (BLS state data, CareerOneStop), national (BLS OOH) and global (other countries’ statistics) figures, noting cost of living and currency.','Job outlook projects about ten years of change; explain drivers such as an aging population, chronic disease, technology and outpatient care.','Present balanced benefits (pay, security, advancement, helping patients) and challenges (physical and emotional demands, schedules, exposure risks, education cost) with how professionals manage them; show numbers in clear tables or charts.'],terms:[['Median wage','The middle wage value for an occupation.'],['Job outlook','Projected change in employment over about ten years.'],['Entry-level salary','Typical pay for new workers in a career.']],mcqs:[q('Which value is often closest to entry-level pay?','A lower percentile such as the 10th or 25th','The median','The 90th percentile','The highest salary','Lower end.'),q('The median wage means:','Half earn more and half earn less','The average of all wages','The starting wage','The maximum wage','Middle value.'),q('Which source provides national wage data?','BLS Occupational Outlook Handbook','A social media post','A random blog','A movie','Government data.'),q('Which levels of salary does the outline require?','Local, national and global entry-level','Only national median','Only global','None','Rubric item.'),q('Which factor increases demand for many health careers?','Aging population','Fewer patients','Less technology','Shrinking hospitals','Demographics.'),q('Which is a challenge of many health careers?','Night and weekend shifts','Helping patients','Job security','Advancement','Schedules.'),q('What should accompany salary figures?','Source and year','Nothing','Only color','A guess','Credibility.'),q('Why consider cost of living?','A higher salary may not mean more buying power','It is irrelevant','It replaces salary','It is required by law','Context.')],frq:{prompt:'Explain how your team would present salary, outlook, benefits and challenges for a health career accurately and in a balanced way.',rubric:[['Salary',['entry-level','percentile','median','local','national','global','annual','hourly']],['Sources and context',['bls','careeronestop','source','year','cost of living','currency']],['Outlook',['outlook','ten years','aging','chronic','technology','demand']],['Benefits and challenges',['benefits','challenges','schedule','physical','emotional','balanced','manage']]],model:'For respiratory therapy, we would present entry-level salary rather than only the median. Using BLS wage data, we would identify the 25th-percentile annual wage nationally as an entry-level estimate, then find our state’s entry-level figure from BLS state data or CareerOneStop, and compare one other country using that country’s government labor statistics converted to U.S. dollars, noting differences in cost of living, currency and how the profession is organized. Each figure would be labeled as annual or hourly with its source and year in a simple bar chart. If reliable global data were limited, we would say so honestly rather than inventing numbers. For job outlook, we would report the BLS projected growth rate and explain why demand is rising: an aging population with more chronic lung disease such as COPD, ongoing needs from respiratory infections and advances in ventilator and home-care technology. For benefits, we would highlight stable demand, competitive pay, opportunities to specialize in neonatal or critical care and the reward of helping patients breathe, using a quote from the therapist we interviewed. For challenges, we would honestly describe 12-hour night and weekend shifts, emotionally difficult situations with critically ill patients, exposure to infections and continuing education requirements, and explain how professionals manage them through teamwork, protective equipment and self-care. A two-column benefits-and-challenges panel would keep the information balanced and easy to read.'},sources:[RULES,BLS_OOH,COS]};
